import { writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";

// Google MediaPipe canonical face data, Apache-2.0. Reproducible source revision and hash
// are embedded into the generated file; iris landmarks are deliberately excluded.
// Pinned by default. Pass a reviewed 40-character revision explicitly to update data.
const revision = process.argv[2] ?? "a908d668c730da128dfa8d9f6bd25d519d006692";
if(!/^[a-f0-9]{40}$/.test(revision))throw new Error("Expected a pinned Git revision");
const source = `https://raw.githubusercontent.com/google-ai-edge/mediapipe/${revision}/mediapipe/modules/face_geometry/data/canonical_face_model.obj`;
const response = await fetch(source);
if (!response.ok) throw new Error(`Canonical face download failed: ${response.status}`);
const obj = await response.text();
const vertices = [], triangles = [];
for (const line of obj.split(/\r?\n/)) {
  if (line.startsWith("v ")) vertices.push(line.trim().split(/\s+/).slice(1).map(Number));
  if (line.startsWith("f ")) triangles.push(line.trim().split(/\s+/).slice(1).map(value => Number(value.split("/")[0]) - 1));
}
if (vertices.length !== 468 || triangles.some(t => t.length !== 3 || t.some(i => i < 0 || i >= 468))) throw new Error("Unexpected canonical topology");
const output = `// Generated by scripts/generate-face-contact-topology.mjs.\n// Copyright Google LLC. Apache-2.0; see faceContactTopology.NOTICE.md.\nexport const FACE_TOPOLOGY_SOURCE = ${JSON.stringify({ source, revision, sha256: createHash("sha256").update(obj).digest("hex"), vertices: vertices.length, triangles: triangles.length })} as const;\nexport const CANONICAL_FACE_VERTICES: readonly (readonly number[])[] = ${JSON.stringify(vertices)};\nexport const CANONICAL_FACE_TRIANGLES: readonly (readonly number[])[] = ${JSON.stringify(triangles)};\n`;
await writeFile(new URL("../src/lib/avatar-motion/faceContactTopology.ts", import.meta.url), output, "utf8");
const license=await fetch(`https://raw.githubusercontent.com/google-ai-edge/mediapipe/${revision}/LICENSE`);
if(!license.ok)throw new Error("Missing source license");
await writeFile(new URL("../src/lib/avatar-motion/faceContactTopology.LICENSE",import.meta.url),await license.text(),"utf8");
console.log(JSON.stringify({ revision, vertices: vertices.length, triangles: triangles.length }));
